WITH t AS (SELECT {{today}} AS d), yrs AS (SELECT DISTINCT y FROM (SELECT year(d) AS y FROM t UNION ALL SELECT year(d) + 1 FROM t)), e1 AS (SELECT y, y % 19 AS a, y // 100 AS b, y % 100 AS c FROM yrs), e2 AS (SELECT y, a, (19 * a + b - b // 4 - (b - (b + 8) // 25 + 1) // 3 + 15) % 30 AS h, b % 4 AS e, c // 4 AS i, c % 4 AS k FROM e1), e3 AS (SELECT y, a, h, (32 + 2 * e + 2 * i - h - k) % 7 AS l FROM e2), easter AS (SELECT make_date(y, (h + l - 7 * ((a + 11 * h + 22 * l) // 451) + 114) // 31, (h + l - 7 * ((a + 11 * h + 22 * l) // 451) + 114) % 31 + 1) AS es FROM e3), off AS (SELECT make_date(y, m, dd) AS day FROM yrs, (VALUES (1, 1), (1, 6), (5, 1), (5, 3), (8, 15), (11, 1), (11, 11), (12, 24), (12, 25), (12, 26)) v(m, dd) UNION ALL SELECT CAST(es + 1 AS DATE) FROM easter UNION ALL SELECT CAST(es + 60 AS DATE) FROM easter), self AS (SELECT json_extract_string(state,'$.vat_status') AS vat_status, json_extract_string(state,'$.income_tax') AS income_tax FROM objects WHERE object_type = 'company' AND json_extract_string(state,'$.kind') = 'self' LIMIT 1), per AS (SELECT CAST(date_trunc('month', d) - INTERVAL 1 MONTH AS DATE) AS p FROM t UNION ALL SELECT CAST(date_trunc('month', d) AS DATE) FROM t), kinds(kind, dd) AS (VALUES ('vat', 25), ('income', 20)), stat AS (SELECT kind, strftime(p, '%Y-%m') AS period, make_date(year(p + INTERVAL 1 MONTH), month(p + INTERVAL 1 MONTH), dd) AS statutory FROM per, kinds), due AS (SELECT kind, period, (SELECT MIN(c) FROM (SELECT CAST(statutory + CAST(g AS INTEGER) AS DATE) AS c FROM range(0, 10) r(g)) WHERE dayofweek(c) NOT IN (0, 6) AND c NOT IN (SELECT day FROM off)) AS due FROM stat), next AS (SELECT kind, period, due FROM due, t WHERE due >= t.d QUALIFY row_number() OVER (PARTITION BY kind ORDER BY due) = 1), vs AS (SELECT object_id, json_extract_string(state,'$.period') AS period, CAST(json_extract(state,'$.vat_due') AS BIGINT) AS vat_due FROM objects WHERE object_type = 'vat_settlement' AND COALESCE(json_extract_string(state,'$.book'), 'pl-stat') = 'pl-stat'), ca AS (SELECT object_id, json_extract_string(state,'$.period') AS period, CAST(json_extract(state,'$.advance') AS BIGINT) AS advance FROM objects WHERE object_type = 'cit_advance' AND COALESCE(json_extract_string(state,'$.book'), 'pl-stat') = 'pl-stat') SELECT strftime(n.due, '%Y-%m-%d') AS due, CASE WHEN n.kind = 'vat' THEN 'VAT i JPK_V7M' WHEN s.income_tax = 'cit' THEN 'Zaliczka na CIT' WHEN s.income_tax IN ('skala', 'liniowy') THEN 'Zaliczka na PIT' WHEN s.income_tax = 'ryczalt' THEN 'Ryczałt od przychodów' ELSE 'Zaliczka na podatek dochodowy' END AS what, n.period, CASE WHEN n.kind = 'vat' THEN vs.vat_due ELSE ca.advance END AS amount, CASE WHEN n.kind = 'income' AND COALESCE(s.income_tax, '') <> 'cit' THEN 'księgi jeszcze jej nie liczą' WHEN n.kind = 'income' AND ca.object_id IS NULL THEN 'miesiąc jeszcze niezamknięty' WHEN n.kind = 'vat' AND vs.object_id IS NULL THEN 'miesiąc jeszcze niezamknięty' END AS note, COALESCE(vs.object_id, ca.object_id) AS _of FROM next n LEFT JOIN self s ON true LEFT JOIN vs ON n.kind = 'vat' AND vs.period = n.period LEFT JOIN ca ON n.kind = 'income' AND COALESCE(s.income_tax, '') = 'cit' AND ca.period = n.period WHERE NOT (n.kind = 'vat' AND COALESCE(s.vat_status, 'active') = 'exempt') ORDER BY n.due, n.kind
